mapper.select:
SELECT a.*, u.nick_name author_name, u.avatar author_avatar FROM article_info a LEFT JOIN user_info u ON a.user_id = u.user_id WHERE a.article_id IN
#{item}
AND a.status = 1

SELECT a.article_id AS articleId, a.title, a.cover_image AS coverImage, a.summary, a.view_count AS viewCount, a.like_count AS likeCount, a.collect_count AS collectCount, a.publish_time AS publishTime, u.nick_name AS authorName, u.avatar AS authorAvatar FROM article_info a JOIN article_tag_relation atr ON a.article_id = atr.article_id JOIN user_info u ON a.user_id = u.user_id WHERE a.status = 1 AND atr.tag_id IN
#{item}
AND a.article_id NOT IN( SELECT article_id FROM user_action WHERE user_id = #{userId} AND action_type = 7 ) GROUP BY a.article_id ORDER BY( COUNT(atr.tag_id) * 10 + -- 匹配的偏好标签越多，分越高 (a.like_count * 2 + a.collect_count * 3 + a.view_count) / (1 + DATEDIFF(NOW(), a.publish_time) * 0.1) DESC ) LIMIT #{limit}

SELECT a.article_id AS articleId, a.title, a.cover_image AS coverImage, a.summary, a.view_count AS viewCount, a.like_count AS likeCount, a.collect_count AS collectCount, a.publish_time AS publishTime, u.nick_name AS authorName, u.avatar AS authorAvatar FROM article_info a JOIN user_info u ON a.user_id = u.user_id WHERE a.status = 1
AND a.article_id NOT IN
#{item}
ORDER BY (a.like_count * 2 + a.collect_count * 3 + a.view_count) DESC LIMIT #{limit}
